{
  "name": "@gitgen/gitgen",
  "version": "1.1.0",
  "readme": "README.md",
  "description": "Generate code with git. AI-powered code generation that learns your codebase patterns.",
  "type": "module",
  "bin": {
    "git-gen": "./gitgen.ts"
  },
  "main": "./dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "src",
    "gitgen.ts",
    ".agent",
    ".opencode"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "start": "npx tsx gitgen.ts",
    "test": "dotenv -e .env -- vitest run",
    "test:unit": "dotenv -e .env -- vitest run tests/unit",
    "test:integration": "dotenv -e .env -- vitest run tests/integration",
    "test:e2e": "dotenv -e .env -- vitest run tests/e2e",
    "test:e2e:cli": "dotenv -e .env -- vitest run tests/e2e/cli.test.ts",
    "test:e2e:gen": "dotenv -e .env -- vitest run tests/e2e/gen-branch.test.ts",
    "test:e2e:state": "dotenv -e .env -- vitest run tests/e2e/state.test.ts",
    "test:e2e:web": "npx playwright test",
    "test:watch": "dotenv -e .env -- vitest",
    "test:coverage": "dotenv -e .env -- vitest run --coverage"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/gitgen-io/gitgen.git"
  },
  "homepage": "https://github.com/gitgen-io/gitgen#readme",
  "bugs": {
    "url": "https://github.com/gitgen-io/gitgen/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "gitgen",
    "ai",
    "llm",
    "code-generation",
    "anthropic",
    "claude",
    "bedrock",
    "openrouter",
    "opencode",
    "github-actions"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20.0.0"
  },
  "dependencies": {
    "@ai-sdk/amazon-bedrock": "^2.2.0",
    "@ai-sdk/anthropic": "^1.2.0",
    "@ai-sdk/google": "^3.0.10",
    "@ai-sdk/openai": "^3.0.14",
    "@openrouter/ai-sdk-provider": "^0.7.0",
    "ai": "^4.3.0",
    "gray-matter": "^4.0.3",
    "zod": "^3.24.0"
  },
  "peerDependencies": {
    "opencode": ">=0.1.0"
  },
  "peerDependenciesMeta": {
    "opencode": {
      "optional": true
    }
  },
  "devDependencies": {
    "@playwright/test": "^1.58.0",
    "@types/node": "^20.0.0",
    "dotenv-cli": "^8.0.0",
    "tsx": "^4.0.0",
    "typescript": "^5.3.0",
    "vitest": "^3.0.0"
  }
}

